291.sql:
SELECT COUNT(*) AS answer
FROM molecule
WHERE label = '+';

419.sql:
SELECT COUNT(*) AS answer
FROM cards
WHERE `borderColor` = 'borderless' AND `edhrecRank` > 12000;

436.sql:
WITH extendedart_cards AS (
    SELECT `id`
    FROM cards
    WHERE `frameEffects` = 'extendedart'
)
SELECT `id` FROM extendedart_cards;

625.sql:
SELECT COUNT(*) AS answer
FROM users
WHERE Location = 'New York, NY';
